MAP_IMAGE_B64: Final = """"""
MAP_WIDTH: Final = 1000


def load_map_image() -> Image.Image:
    raw = base64.b64decode(MAP_IMAGE_B64)
    return Image.open(io.BytesIO(raw)).convert("RGB")


