def initialize_state() -> None:
    defaults = {
        "screen": "title",
        "show_intro": False,
        "current_step": 0,
        "selected_target": None,
        "show_result": False,
        "show_finish": False,
        "log": [],
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value


def start_app() -> None:
    st.session_state.screen = "main"
    st.session_state.show_intro = True
    st.session_state.current_step = 0
    st.session_state.selected_target = None
    st.session_state.show_result = False
    st.session_state.show_finish = False
    st.session_state.log = []


def reset_app() -> None:
    for key in list(st.session_state.keys()):
        del st.session_state[key]
    st.rerun()


def find_target(x: int, y: int) -> str | None:
    for target, x1, y1, x2, y2 in HOTSPOTS:
        if x1 <= x <= x2 and y1 <= y <= y2:
            return target
    return None


def complete_current_step() -> None:
    step = STEPS[st.session_state.current_step]
    st.session_state.log.append(step)
    st.session_state.show_result = True


def move_to_next_step() -> None:
    st.session_state.show_result = False
    st.session_state.selected_target = None
    if st.session_state.current_step == len(STEPS) - 1:
        st.session_state.show_finish = True
    else:
        st.session_state.current_step += 1


@st.dialog("状況説明・アプリの使い方")
def intro_dialog() -> None:
    st.markdown(
        """
あなたは新しいパソコン（画像中の **PC②**）を買い、
自宅のローカル通信ネットワークに接続しました。

しかし、新しいパソコンでは通信障害が起きています。

**画面内の機器をクリックし、原因を特定しよう。**
"""
    )
    st.divider()
    st.markdown(
        """
### 使い方

1. 画面内のPC・ハブ・有線LANをクリックします。
2. 表示された確認項目を実行します。
3. 確認後のポップアップで結果を読み取ります。
4. 調査は順番に進みます。
5. すべての調査が終わるとシミュレーションは終了します。
"""
    )
    st.info("有線LANは、ケーブル本体と吹き出しのどちらをクリックしても選択できます。")
    if st.button("調査を開始する", type="primary", use_container_width=True):
        st.session_state.show_intro = False
        st.rerun()


@st.dialog("確認が終わりました")
def result_dialog() -> None:
    step = STEPS[st.session_state.current_step]
    st.success(step["result"])
    st.markdown("### この結果から分かること")
    st.info(step["meaning"])
    if st.button("次へ進む", type="primary", use_container_width=True):
        move_to_next_step()
        st.rerun()


@st.dialog("調査終了")
def finish_dialog() -> None:
    st.markdown(
        """
## すべての確認が終わりました

今回の調査では、通信障害の原因を**一つに特定することはできませんでした**。

しかし、確認を重ねることで、原因ではない可能性が高い部分を明らかにし、
原因候補を大きく絞り込むことができました。
"""
    )
    st.markdown("### 可能性が低くなった原因")
    eliminated = []
    for step in st.session_state.log:
        eliminated.extend(step["eliminates"])
    for item in dict.fromkeys(eliminated):
        st.write(f"✅ {item}")
    st.success(
        "原因を特定できなかったことは失敗ではありません。"
        "切り分けができたことが、今回の調査の成果です。"
    )
    if st.button("タイトルへ戻る", use_container_width=True):
        reset_app()


